theme.css:
/* Big Picture by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { min-height:min(900px, 90dvh); }
.ip-hero .ip-header { text-align:center; max-width:1120px; margin:auto; align-self:center; }
.ip-title { max-width:100%; font-size:clamp(var(--pager-title-min-size), calc(1rem + 3vw), var(--pager-title-size)); letter-spacing:-.045em; }
.ip-description { margin-inline:auto; }
.ip-hero .ip-navigation { justify-content:center; padding-block:16px; }
.ip-block { padding-block:48px; }
.ip-block .block-heading { text-align:center; }
@media(max-width:760px) { .ip-hero { min-height:70dvh; } }

.ip-hero:has(.ip-banner)::after { background:linear-gradient(#0009,#000b); }
.ip-hero:has(.ip-banner) .ip-description { color:#ffffff; opacity:1; }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
